INSERT INTO `about_us` (`id`, `header_title`, `mission`, `vision`, `values_text`, `background`, `created_at`) VALUES
(1, 'Mana Murtii Ol\'aanaa Magaalaa Shaashamannee', 'Bu\'aa  Qorannoo \'Dhaddacha Ijibbaataa Mana Murtii Waliigalaa Oromiyaa: Xiinxala Seeraa fi Hojimaataa\' jedhu  Inistiitiyuutii Leenjii fi Qorannoo Seeraa Oromiyaatiin Qophaa\'ee fi Bu\'aa Odiitii Galmee Murtiin Boodaa Irratti Mariin Gaggeeffameera. Dhaddachi Ijibbaataa MMWO ergama akka waliigalaatti Manneen Murtii Naannoo Oromiyaaf Labsii lakk.216/11 keewwata 23(1) jalatti kaayame kan qooddatu akkuma jiruun ta’ee,tajaajilli  abbaa  seerummaa Naannicha keessatti walfakkaatummaa fi tilmaamamummaa akka qabaatuuf kan  hojjatu ta\'uu  Labsicha keewwata 23(2a) jalatti tumamee jira.Dhaddachi Ijibbaataa MMWO ergama seeraan itti kenname kana sirnaan bahachaa jiraachuun wal qabatee ciminootaa fi hanqinaalee mul\'atan irratti qorannoo ILQSOn gaggeessaa turee fi harcaatiiwwan odiitii galmee murtiin boodaatiin adda bahan irratti abbootii seeraa Dhaddacha Ijibbaataa waliin mariin gaggeeffameera.\r\nWaltajjii marii kana irratti argamuun kallattii hojii kan kaa\'an Pirezidaantii Mana Murtii Waliigalaa Kabajamoo Otukkannaa Odaa (PhD),dhimmoota Dhaddacha Ijibbaataatti dhiyaachuu qaban irratti hubannaan qaamolee gara garaa fi ogeessota seeraa bira jiru hanqina waan qabuuf yeroo ammaa kana dhaddachi ijibbaataa dhimmoota hiikkoo seeraa barbaadanitti hiikkoo kennuu keessaa bahee dhimmoota mana murtii idileetti dhiyaachuu qabaniin dhiphataa kan jiru ta\'uu himan.', ' Gama biroon barri keessa jirru bara \'AI\' ta\'uun hubatamee Abbootiin Seeraa keenya jijjiirama teekinooloojii addunyaan bira geesse  waliin deemuuf of gahoomsaa  deemuu qabu jedhan.\r\nKallattii haqa mirkaneessuutiin hojiiwwan hojjataman kan jiran ta\'us bakka gahuu qabnu bira kan hin geenye ta’uun hubatame waan xixiqqaatti quufnee ciisuu irra ciminaan hojjatamuu qaba jedhan.Madaalliin keenya haqni kennamaa jiru qotee bulaa fi hawaasa keenya kan boqochiisee fi baasii irraa hambise ta’uun madaalamuus  qaba jedhan.Hojii hojjatamaa jiru keessattis uummanni maal nuun jedhaa jiraa  kan jedhu of  dhaggeeffachaa deemamuu kan qabu ta\'uis dhaaman.', 'Si’oominnii  fi qulqullinni Kenniinsa tajaajila abbaa seerummaa deemsa baratamaa keessaa bahee  haala wal madaalawaa ta’een deemuu kan qabu ta\'uu dhaaman.', 'Waltajjii marii kana irratti argamuun kallattii hojii kan kaa\'an Pirezidaantii Mana Murtii Waliigalaa Kabajamoo Otukkannaa Odaa (PhD),dhimmoota Dhaddacha Ijibbaataatti dhiyaachuu qaban irratti hubannaan qaamolee gara garaa fi ogeessota seeraa bira jiru hanqina waan qabuuf yeroo ammaa kana dhaddachi ijibbaataa dhimmoota hiikkoo seeraa barbaadanitti hiikkoo kennuu keessaa bahee dhimmoota mana murtii idileetti dhiyaachuu qabaniin dhiphataa kan jiru ta\'uu himan.\r\n Gama biroon barri keessa jirru bara \'AI\' ta\'uun hubatamee Abbootiin Seeraa keenya jijjiirama teekinooloojii addunyaan bira geesse  waliin deemuuf of gahoomsaa  deemuu qabu jedhan.\r\nKallattii haqa mirkaneessuutiin hojiiwwan hojjataman kan jiran ta\'us bakka gahuu qabnu bira kan hin geenye ta’uun hubatame waan xixiqqaatti quufnee ciisuu irra ciminaan hojjatamuu qaba jedhan.Madaalliin keenya haqni kennamaa jiru qotee bulaa fi hawaasa keenya kan boqochiisee fi baasii irraa hambise ta’uun madaalamuus  qaba jedhan.Hojii hojjatamaa jiru keessattis uummanni maal nuun jedhaa jiraa  kan jedhu of  dhaggeeffachaa deemamuu kan qabu ta\'uis dhaaman.\r\nDhaddachi Ijibbaataa bakka uummanni keenya haqa isaa itti jibbaatu waan  ta\'eef abbootiin seeraa gahumsaa fi dandeettii seera hiikuu isaanii gabbisuun baankii yaadaa ta’uun irraa eegama jedhan.\r\nSi’oominnii  fi qulqullinni Kenniinsa tajaajila abbaa seerummaa deemsa baratamaa keessaa bahee  haala wal madaalawaa ta’een deemuu kan qabu ta\'uu dhaaman.\r\nWaltajjii marii kana irratti Abbootiin Seeraa Dhaddacha Ijibbaataa argamaniiru.', '2026-10-26 13:17:47');
