INSERT INTO `feedback_submissions` (`id`, `full_name`, `email`, `phone`, `department`, `message`, `attachment_path`, `status`, `created_at`) VALUES
(1, 'Dajane Urgeessaa', 'dejeneurgessa1@gmail.com', 915674694, 'MMO Magaalaa Shaggar', 'In React applications, dropdown menus are typically implemented as controlled components, with state managing the selected value. While React’s built-in event handling makes it easy to create basic dropdowns, more advanced use cases benefit from third-party libraries that enhance functionality and accessibility.', 'uploads/1793561575_news.png', 'seen', '2026-11-07 06:45:29'),
(2, 'Dajane Urgeessaa', 'dejeneurgessa1@gmail.com', 915674694, 'MMO Magaalaa Shaggar', 'In React applications, dropdown menus are typically implemented as controlled components, with state managing the selected value. While React’s built-in event handling makes it easy to create basic dropdowns, more advanced use cases benefit from third-party libraries that enhance functionality and accessibility.', 'uploads/1793561704_news.png', 'seen', '2026-11-07 06:44:57'),
(3, 'Chala Milkeessoo', 'chala@gmail.com', 926499871, 'MMO Magaalaa Shaashamannee', 'Qophiin Digitalisation fi E court wal qabatee Documentariin ETV MMO Magaalaa Shaashamannee wajjiin wal ta\'uun qopheesse har\'a galgala sa\'aatii 3:00 irratti ETV NEWS irraan waan darbuuf akka hordoftan kabajaan isin beeksifna.', 'uploads/1794034121_kar.jpg', 'seen', '2026-11-07 06:49:01'),
(4, 'Karoorsaa Sharkamaa', 'kerorsa959@gmail.com', 2147483647, 'Waajjira Naamusa', 'Hojjattoonnis kutannoo (commitment) guutudhaan hawaasa isaaniitiif tajaajila abbaa seerummaa qulqulluu, haqa-qabeessa fi yeroo isaa eeggate akka kennan Pirezdaantii MMO Magaalaa Shaashamannee ergaa dabarsaniiru.', 'uploads/1794035036_ragga\'ee fi hin dhiyeessisu.PDF', 'seen', '2026-11-07 07:04:33'),
(5, 'Rast name his', '', 0, 'MMO Magaalaa Shaashamannee', 'Lakk galmee armaan gadii jiruu irraati haala qajeelfaman waan na keessumeessineef eeruu kennu dha', 'uploads/1794216859_arsii lixaatif.pdf', 'seen', '2026-11-09 09:37:40'),
(6, 'Worquu Garishuu Badhilee', 'garishuwarqu@gmail.com', 946863794, 'MMO Magaalaa Shaashamannee', 'Lakk galmee 367845 tae qulqullinan kan na hin keessummeessine waan taaef eeruu kennu ta\'a', 'uploads/1794217009_arsii lixaatif.pdf', 'seen', '2026-11-09 09:37:32'),
(7, 'Dejene Urgessa', 'dejeneurgessa1@gmail.com', 911234565, 'Waajjira Naamusa', 'Here is the updated source code. It has been redesigned with a gorgeous, professional Tailwind CSS layout featuring a sleek top toggle switcher that lets users switch between Case Appointment Registration and a smart SMS Credit / Account Top-Up panel, complete with modern icons, smooth transitions, and fully preserved backend PHP logic.', 'uploads/1794375020_send-reminders.php', '', '2026-11-11 05:30:20');
