INSERT INTO `news` (`id`, `title`, `publish_date`, `image_path`, `summary`, `content`) VALUES
(2, 'Gabaasa kurmaana 1ffaa', '2026-10-26', 'uploads/news/1793021936_1792497677963.jpg', 'manni murtii olaa', 'Waltajjii marii kana irratti argamuun kallattii hojii kan kaa\'an Pirezidaantii Mana Murtii Waliigalaa Kabajamoo Otukkannaa Odaa (PhD),dhimmoota Dhaddacha Ijibbaataatti dhiyaachuu qaban irratti hubannaan qaamolee gara garaa fi ogeessota seeraa bira jiru hanqina waan qabuuf yeroo ammaa kana dhaddachi ijibbaataa dhimmoota hiikkoo seeraa barbaadanitti hiikkoo kennuu keessaa bahee dhimmoota mana murtii idileetti dhiyaachuu qabaniin dhiphataa kan jiru ta\'uu himan.\r\n Gama biroon barri keessa jirru bara \'AI\' ta\'uun hubatamee Abbootiin Seeraa keenya jijjiirama teekinooloojii addunyaan bira geesse  waliin deemuuf of gahoomsaa  deemuu qabu jedhan.\r\nKallattii haqa mirkaneessuutiin hojiiwwan hojjataman kan jiran ta\'us bakka gahuu qabnu bira kan hin geenye ta’uun hubatame waan xixiqqaatti quufnee ciisuu irra ciminaan hojjatamuu qaba jedhan.Madaalliin keenya haqni kennamaa jiru qotee bulaa fi hawaasa keenya kan boqochiisee fi baasii irraa hambise ta’uun madaalamuus  qaba jedhan.Hojii hojjatamaa jiru keessattis uummanni maal nuun jedhaa jiraa  kan jedhu of  dhaggeeffachaa deemamuu kan qabu ta\'uis dhaaman.\r\nDhaddachi Ijibbaataa bakka uummanni keenya haqa isaa itti jibbaatu waan  ta\'eef abbootiin seeraa gahumsaa fi dandeettii seera hiikuu isaanii gabbisuun baankii yaadaa ta’uun irraa eegama jedhan.\r\nSi’oominnii  fi qulqullinni Kenniinsa tajaajila abbaa seerummaa deemsa baratamaa keessaa bahee  haala wal madaalawaa ta’een deemuu kan qabu ta\'uu dhaaman.\r\nWaltajjii marii kana irratti Abbootiin Seeraa Dhaddacha Ijibbaataa argamaniiru.'),
(5, ' Yaa\'ii Abbootii Seeraa Manneen Murtii Magaalaa Shaashamannee Marsaa 3ffaa ', '2026-10-30', 'uploads/news/1793347156_xx.jpg', 'Yaa\'ii Abbootii Seeraa Manneen Murtii Magaalaa Shaashamannee Marsaa 3ffaa sababeeffachuudhaan marii abbootii seeraa wajjiin Laangannoo Ijaa Risoortitti gaggeeffamee jira. ', '𝐚𝐚\'𝐢𝐢 𝐀𝐛𝐛𝐨𝐨𝐭𝐢𝐢 𝐒𝐞𝐞𝐫𝐚𝐚 𝐌𝐚𝐧𝐧𝐞𝐞𝐧 𝐌𝐮𝐫𝐭𝐢𝐢 𝐌𝐚𝐠𝐚𝐚𝐥𝐚𝐚 𝐒𝐡𝐚𝐚𝐬𝐡𝐚𝐦𝐚𝐧𝐧𝐞𝐞 𝐌𝐚𝐫𝐬𝐚𝐚 𝟑𝐟𝐟𝐚𝐚 𝐒𝐚𝐛𝐚𝐛𝐞𝐞𝐟𝐟𝐚𝐜𝐡𝐮𝐮𝐝𝐡𝐚𝐚𝐧 𝐌𝐚𝐫𝐢𝐢 𝐀𝐛𝐛𝐨𝐨𝐭𝐢𝐢 𝐒𝐞𝐞𝐫𝐚𝐚 𝐖𝐚𝐣𝐣𝐢𝐢𝐧 𝐋𝐚𝐚𝐧𝐠𝐚𝐧𝐧𝐨𝐨 𝐈𝐣𝐚𝐚 𝐑𝐢𝐬𝐨𝐨𝐫𝐭𝐢𝐭𝐭𝐢 𝐠𝐚𝐠𝐠𝐞𝐞𝐟𝐟𝐚𝐦𝐞𝐞 𝐣𝐢𝐫𝐚.\r\n    \r\n        Adoolessa 19, 2018\r\n         𝑆ℎ𝑎𝑎𝑠ℎ𝑎𝑚𝑎𝑛𝑛𝑒𝑒  \r\n             ••••••••••••\r\n\r\nYaa\'ii Abbootii Seeraa Manneen Murtii Magaalaa Shaashamannee Marsaa 3ffaa sababeeffachuudhaan marii abbootii seeraa wajjiin Laangannoo Ijaa Risoortitti gaggeeffamee jira. \r\n\r\nMarii kana irratti dhiyeessiin mata duree \"Meeshaalee Sirna  Kakuu Aadaa gara Mana Murtii Idileetti fiduun fayyadamuun  bu\'aa haqa baasuu keessatti qabuu fi Komii Naamusaa fi Hanqinnoota Xiinxala Sadarkeessa Naamusaa Manneen Murtii Magaalaa Shaashamannee\"  jedhu  irratti xiinxalli gadi fagoo akka manneen murtii magaalaa shaashamanneetti gaggeeffamaa ture karaa Garee Naamusaa fi Inispeekshiinii MMO Magaalaa Shaashamanneetiin erga dhiyaatee booda hirmaattonni marii  keessaa yaada kaasuudhaan mariin  bal\'aan irratti gaggeeffamee jira. Waggoottan darban waliin yoo ilaallamu dhimmoonni naamusaa fooyyee qabaachuu isaa dhiyeessii kanarraa hubatameera.\r\n\r\nPirezdaantiin MMO Magaalaa Shaashamannee Abbootii Seeraa Manneen Murtii Magaalaa  Raawwii Ol\'aanaa galmaa\'eef Abbootii Seeraa ifatti galateeffatanii jiru.\r\n\r\nItti dabaluunis haqummaan kan mirkanaa\'u naamusaa fi amanamummaa abbaa seeraa irraa kan eegalu ta\'uu ibsanii naamusni abbootii seeraa caalaatti akka cimuu fi hawaasni murtii seeraa irratti amantaa guutuu akka qabaatuuf kallattiin qulqullina hojii fooyyessu kaa\'uudhaan maricha goolabaniiru.\r\n\r\n#Shaashamannee #ManneenMurtii #Haqummaa #AbbootiiSeeraa #IjaResort #Oromia'),
(6, 'Daawwii fi Marii Abbootii Seeraa Laangannoo Ija Resoortitti', '2026-06-02', 'uploads/news/1793606758_mar.jpg', '𝐘𝐚𝐚\'𝐢𝐢 𝐀𝐛𝐛𝐨𝐨𝐭𝐢𝐢 𝐒𝐞𝐞𝐫𝐚𝐚 𝐌𝐚𝐧𝐧𝐞𝐞𝐧 𝐌𝐮𝐫𝐭𝐢𝐢 𝐌𝐚𝐠𝐚𝐚𝐥𝐚𝐚 𝐒𝐡𝐚𝐚𝐬𝐡𝐚𝐦𝐚𝐧𝐧𝐞𝐞 𝐌𝐚𝐫𝐬𝐚𝐚 𝟑𝐟𝐟𝐚𝐚 𝐒𝐚𝐛𝐚𝐛𝐞𝐞𝐟𝐟𝐚𝐜𝐡𝐮𝐮𝐝𝐡𝐚𝐚𝐧 𝐌𝐚𝐫𝐢𝐢 𝐀𝐛𝐛𝐨𝐨𝐭𝐢𝐢 𝐒𝐞𝐞𝐫𝐚𝐚 𝐖𝐚𝐣𝐣𝐢𝐢𝐧 𝐋𝐚𝐚𝐧𝐠𝐚𝐧𝐧𝐨𝐨 𝐈𝐣𝐚𝐚 𝐑𝐢𝐬𝐨𝐨𝐫𝐭𝐢𝐭𝐭𝐢 𝐠𝐚𝐠𝐠𝐞𝐞𝐟𝐟𝐚𝐦𝐞𝐞 𝐣𝐢𝐫𝐚.', '𝐘𝐚𝐚\'𝐢𝐢 𝐀𝐛𝐛𝐨𝐨𝐭𝐢𝐢 𝐒𝐞𝐞𝐫𝐚𝐚 𝐌𝐚𝐧𝐧𝐞𝐞𝐧 𝐌𝐮𝐫𝐭𝐢𝐢 𝐌𝐚𝐠𝐚𝐚𝐥𝐚𝐚 𝐒𝐡𝐚𝐚𝐬𝐡𝐚𝐦𝐚𝐧𝐧𝐞𝐞 𝐌𝐚𝐫𝐬𝐚𝐚 𝟑𝐟𝐟𝐚𝐚 𝐒𝐚𝐛𝐚𝐛𝐞𝐞𝐟𝐟𝐚𝐜𝐡𝐮𝐮𝐝𝐡𝐚𝐚𝐧 𝐌𝐚𝐫𝐢𝐢 𝐀𝐛𝐛𝐨𝐨𝐭𝐢𝐢 𝐒𝐞𝐞𝐫𝐚𝐚 𝐖𝐚𝐣𝐣𝐢𝐢𝐧 𝐋𝐚𝐚𝐧𝐠𝐚𝐧𝐧𝐨𝐨 𝐈𝐣𝐚𝐚 𝐑𝐢𝐬𝐨𝐨𝐫𝐭𝐢𝐭𝐭𝐢 𝐠𝐚𝐠𝐠𝐞𝐞𝐟𝐟𝐚𝐦𝐞𝐞 𝐣𝐢𝐫𝐚.\r\n    \r\n        Adoolessa 19, 2018\r\n         𝑆ℎ𝑎𝑎𝑠ℎ𝑎𝑚𝑎𝑛𝑛𝑒𝑒  \r\n             ••••••••••••\r\n\r\nYaa\'ii Abbootii Seeraa Manneen Murtii Magaalaa Shaashamannee Marsaa 3ffaa sababeeffachuudhaan marii abbootii seeraa wajjiin Laangannoo Ijaa Risoortitti gaggeeffamee jira. \r\n\r\nMarii kana irratti dhiyeessiin mata duree \"Meeshaalee Sirna  Kakuu Aadaa gara Mana Murtii Idileetti fiduun fayyadamuun  bu\'aa haqa baasuu keessatti qabuu fi Komii Naamusaa fi Hanqinnoota Xiinxala Sadarkeessa Naamusaa Manneen Murtii Magaalaa Shaashamannee\"  jedhu  irratti xiinxalli gadi fagoo akka manneen murtii magaalaa shaashamanneetti gaggeeffamaa ture karaa Garee Naamusaa fi Inispeekshiinii MMO Magaalaa Shaashamanneetiin erga dhiyaatee booda hirmaattonni marii  keessaa yaada kaasuudhaan mariin  bal\'aan irratti gaggeeffamee jira. Waggoottan darban waliin yoo ilaallamu dhimmoonni naamusaa fooyyee qabaachuu isaa dhiyeessii kanarraa hubatameera.\r\n\r\nPirezdaantiin MMO Magaalaa Shaashamannee Abbootii Seeraa Manneen Murtii Magaalaa  Raawwii Ol\'aanaa galmaa\'eef Abbootii Seeraa ifatti galateeffatanii jiru.\r\n\r\nItti dabaluunis haqummaan kan mirkanaa\'u naamusaa fi amanamummaa abbaa seeraa irraa kan eegalu ta\'uu ibsanii naamusni abbootii seeraa caalaatti akka cimuu fi hawaasni murtii seeraa irratti amantaa guutuu akka qabaatuuf kallattiin qulqullina hojii fooyyessu kaa\'uudhaan maricha goolabaniiru.\r\n\r\n#Shaashamannee #ManneenMurtii #Haqummaa #AbbootiiSeeraa #IjaResort #Oromia'),
(7, '𝐆𝐚𝐦𝐚𝐚𝐠𝐠𝐚𝐦𝐧𝐢 𝐑𝐚𝐚𝐰𝐰𝐢𝐢 𝐇𝐨𝐣𝐢𝐢 𝐖𝐚𝐠𝐠𝐚𝐚 𝐌𝐚𝐧𝐚 𝐌𝐮𝐫𝐭𝐢𝐢 𝐖𝐚𝐥𝐢𝐢𝐠𝐚𝐥𝐚 𝐎𝐫𝐨𝐦𝐢𝐲𝐚𝐚  𝐌𝐚𝐠𝐚𝐚𝐥𝐚𝐚 𝐒𝐡𝐚𝐚𝐬𝐡𝐚𝐦𝐚𝐧𝐧𝐞𝐞𝐭𝐭𝐢 𝐆𝐚𝐠𝐠𝐞𝐞𝐟𝐚𝐦e', '2026-11-02', 'uploads/news/1793607066_marii2.jpg', '𝐆𝐚𝐦𝐚𝐚𝐠𝐠𝐚𝐦𝐧𝐢 𝐑𝐚𝐚𝐰𝐰𝐢𝐢 𝐇𝐨𝐣𝐢𝐢 𝐖𝐚𝐠𝐠𝐚𝐚 𝐌𝐚𝐧𝐚 𝐌𝐮𝐫𝐭𝐢𝐢 𝐖𝐚𝐥𝐢𝐢𝐠𝐚𝐥𝐚 𝐎𝐫𝐨𝐦𝐢𝐲𝐚𝐚  𝐌𝐚𝐠𝐚𝐚𝐥𝐚𝐚 𝐒𝐡𝐚𝐚𝐬𝐡𝐚𝐦𝐚𝐧𝐧𝐞𝐞𝐭𝐭𝐢 𝐆𝐚𝐠𝐠𝐞𝐞𝐟𝐚𝐦𝐚𝐚 𝐭𝐮𝐫𝐞 𝐌𝐢𝐥𝐤𝐢𝐢𝐧 𝐆𝐨𝐥𝐚𝐛𝐚𝐦𝐞!', 'Gamaaggamni Raawwii Hojii  Manneen Murtii Waliigala Oromiyaa hojiiwwan waggaa guyyoota lamaaf Magaalaa Shaashamannetti  Qindeessummaa MMO Magaalaa Shaashamannee fi MMO Godina Arsii Lixaatiin gaggeessaa ture milkiin xumureera.\r\n\r\nGamaaggama Raawwii Hojii Waggaa Mana Murtii Waliigala Oromiyaa kana irratti Hoggansa Sadarkaa Aanaa hanga Mana Murtii Waliigalatti kan hirmaachise yoo ta\'u; Gamaaggamicha irratti keessummoota Godinaalee fi  Magaalaa 27 irraa hirmaataniif  Hawaasni Magaalaa Shaashamannee simannaa gaarii taasisaniifii jiru.\r\n\r\n      𝐆𝐚𝐥𝐚𝐭𝐚 𝐀𝐝𝐝𝐚𝐚\r\n        •••••••••••••••\r\nQophii kana jalqabaa hanga xumuratti deeggarsaa fi hordoffii nu faana gochuudhaan simannaa gaarii fi kabaja keessummootaaf agarsiiftaniif  Bulchiinsi Magaalaa Shaashamannee fi Godinni Arsii Lixaa gamaaggamichi galma yaadameen milkiin akka xumuramuuf deeggarsa gootaniif Manni Murtii Ol\'aanaa Magaalaa Shaashamannee maqaa hawaasa Manneen Murtii keenyaatiin isin galateeffanna!!\r\n    \r\n     𝐎𝐝𝐞𝐞𝐟𝐟𝐚𝐧𝐧𝐨𝐨 𝐃𝐚𝐛𝐚𝐥𝐚𝐭𝐚𝐚𝐟\r\n\r\n👉Website: www.schcourt.gov.et/court\r\n\r\n👉Telegram channel https://t.me/+HHPfi38cVpY2M2Y0\r\n\r\n👉Facebook: https://www.facebook.com/profile.php?id=61550199127005');
