INSERT INTO `qa_questions` (`id`, `question`, `answer`, `status`, `created_at`, `answered_at`, `updated_at`) VALUES
(1, 'Dursaan Garee TQO Mana Murtii Ol\'aanaa Magaalaa Shaashamannee eenyu?\r\nDursaa TQO, Obbo Dajanee Urgeessaa,', 'Obbo Dajanee Urgeessaa Jedhama. Birroon isaanii darbii 1ffaa lakkoofsa 11 irratti argamu.\r\nBilbilli isaanii 0926499878 qunnamuu dandeettu.', 'answered', '2026-11-09 09:50:25', '2026-11-09 09:52:05', '2026-11-09 11:27:32'),
(3, 'Teessoo Mana Murtii Ol\'aanaa Magaalaa Shaashamannee eessa?', 'Teessoon Mana Murtii Ol\'aanaa Magaala Shaashamannee kutaa magaalaa Haruufaa, Naannawaa addaa keellaa jedhamutti argama.', 'answered', '2026-11-09 09:55:59', '2026-11-09 09:55:59', '2026-11-09 09:55:59'),
(6, 'Pirezdaantiin aanaa kutaa magaalaa malkaa sirbaa', 'Pirezdaantiin aanaa kutaa magaalaa malkaa sirbaa kabajamoo Obbo Tolosaa Girmaa Dabaluuti', 'answered', '2026-11-09 11:19:46', '2026-11-09 11:20:25', '2026-11-09 11:25:30'),
(8, 'pirezdaantii Aanaa kutaa Magaalaa Allachee', 'Pirezdaantiin Aanaa kutaa Magaalaa Allachee Kabajamoo Obbo Mohaammad Kamaal dha.', 'answered', '2026-11-09 11:23:30', '2026-11-09 11:24:44', '2026-11-09 11:24:44'),
(9, 'Obbo Dajanee Urgeessaa beettaa', 'Eeyyen nan beeka. Obbo Dajanee Urgeessaa Dursaa Garee TQO Mana Murtii Ol\'aanaa Magaalaa Shaashamannee yoo ta\'an, yeroo ammaa hojiiwwan misooma software irrattis bobba\'anii hojiiwwan garagaraa hojjaachaa jiru.', 'answered', '2026-11-09 11:28:06', '2026-11-09 11:52:19', '2026-11-09 11:52:19'),
(10, 'Kutaa Magaalaa Haruufaa irratti odeeffannoo naaf kennuu dandeessaa?, MMAKM haruufaa, harufa woreda sub-city woreda court,', 'manni murtii aanaa kutaa magaalaa haruufaa, manneen murtii aanaa kutaa magaalaa manneen murtii shaashamannee keessaa tokko yoo ta\'an, yeroo ammaa tajaajila abbaa seerummaa kennuu irratti argama.\r\nteessoon mana murtii kanaas magaalaa Shaashamannee kutaa magaalaa haruufaa yoo ta\'u yeroo ammaa teessoon isaa hoteela radi\'eet jedhamu duubatti argama', 'answered', '2026-11-09 11:55:49', '2026-11-09 11:59:56', '2026-11-09 11:59:56'),
(12, 'Duraa tqo', NULL, 'pending', '2026-11-09 12:12:01', NULL, '2026-11-09 12:12:01'),
(14, 'MAKM ALLACHEE', NULL, 'pending', '2026-11-09 12:13:42', NULL, '2026-11-09 12:13:42'),
(18, 'Said Huseen Eennu?', 'Obbo Sa\'id Huseen Abbaa Adeemsa Bittaa fi faayinaansii MMO Magaalaa Shaashamanneeti.', 'answered', '2026-11-09 12:25:59', '2026-11-09 12:26:59', '2026-11-09 12:26:59'),
(23, 'Obo dajane beettaa', NULL, 'pending', '2026-11-09 14:57:36', NULL, '2026-11-09 14:57:36'),
(24, 'said huseen beettaa', NULL, 'pending', '2026-11-09 14:58:16', NULL, '2026-11-09 14:58:16'),
(25, 'worquu beettaa', NULL, 'pending', '2026-11-09 15:05:51', NULL, '2026-11-09 15:05:51'),
(26, 'Galmee banuuf maaltu na barbaachisa?\r\nGalmee banuu barbaada?\r\nulaagaa galmee haaraa banachuu naaf himi', 'galmee haaraya banachuudhaaf :\r\n1. iyyata qopheeffachuu\r\n2. Galmee hariiroo hawaasaa irratti kaffaltii abbaa seerummaa kaffaluu\r\n3. himata kallattii yoo ta\'e kutaa ofiseera seeraatti dhiyeeffachuu\r\n4. oliyyata yoo ta\'e immoo karaa e-faayilingiidhaan ofiseera seeraa gallmee isinii banuu', 'answered', '2026-11-09 15:23:47', '2026-11-09 15:23:47', '2026-11-09 15:23:47');
