INSERT INTO `staff` (`id`, `name`, `role`, `department`, `photo_url`, `bio`) VALUES
(2, 'Obbo Yuusuf Qaalluu', 'Pireezdaantii', 'Court Administration', 'uploads/staff/1793016029_pirezda.jpg', 'Pirezdaantiin Mana Murtii Ol\'aanaa  ergaa dabarsaniin, harcaatiiwwan sasalphaa gama  si\'oominna, qulqullina fi bu\'a qabeessummaa irratti mul\'atan maqsuudhaan tajaajila saffisaa fi si\'aawaa  irratti xiyyeeffannoo ol\'aanaa kennuudhaan fuulduraafis caalaatti'),
(3, 'Dejene Urgessa', 'ICT Directorate', 'Court Administration', 'uploads/staff/1793132421_djuu.jpg', 'Throughout my career, I have successfully led and supported critical technology initiatives. Currently serving as the Software Development Coordinator and Supervisor at Shashemene City High Court, I oversee core IT operations, direct the implementation of'),
(4, 'Sa\'id Huseen Daalee', 'Abbaa Adeemsa Bulchiinsaa fi Faayinaansii', 'Court Administration', 'uploads/staff/1793215067_said.jpg', 'Abbaa Adeemsa Bulchiinsaa fi faayinaansii MMO Magaalaa Shaashamannee'),
(5, 'Obbo Karoorsaa Sherkamaa Guutuu', 'Abbaa Adeemsa Qophii Karooraa fi Baajataa', 'Court Administration', 'uploads/staff/1793611268_kar.jpg', '\r\nYaadni dhiyeessii fi tajaajila Mana Murtii Murtii Magaalaa Shaashamannee ilaalchisee hawaasa irraa ka’us baay\'ee gaarii fi jajjabeessaa kan ture ta\'uu isaa  Hawaasnis tajaajila haqa irratti hundaa\'e fi saffisaa ta\'e argachuu isaaniitti gammachuu guutuu ');
